static TreeNode *parseOperand(const string &s, size_t &pos)
{
	skipSpaces(s, pos);
	if (pos < s.size() && s[pos] == '(') {
		pos++;
		TreeNode *node = parseExpr(s, pos);
		skipSpaces(s, pos);
		if (pos < s.size() && s[pos] == ')')
			pos++;
		return node;
	}
	return new TreeNode("LEAF", readWord(s, pos));
}

